def extract_values(res) -> dict:
    """Pull the claim-relevant numbers out of a PipelineResult (all computed).

    Cluster numbering follows ``res.cluster_ids`` (one id per variable, as
    produced by :func:`src.method.map_cluster_labels`); the row of S/P that a
    cluster number occupies is its position in ``sorted(set(cluster_ids))``.
    Values that cannot be formed for the given run (e.g. a subset with a
    different cluster structure) are reported as ``None`` instead of raising.
    """
    L = res.pca["abs_loadings"]
    vi = {nm: i for i, nm in enumerate(res.variables)}
    ks = sorted(set(int(x) for x in res.cluster_ids))          # cluster numbers, e.g. [1, 2]
    ci = {k: i for i, k in enumerate(ks)}                      # cluster number -> row of S/P

    def S_of(cluster: int, pc: int):
        row = ci.get(cluster)
        return None if row is None or pc >= res.S.shape[1] else float(res.S[row, pc])

    def P_of(cluster: int, pc: int):
        row = ci.get(cluster)
        return None if row is None or pc >= res.P.shape[1] else float(res.P[row, pc])

    evr = res.pca["explained_variance_pct"]
    return {
        "S_C1_PC1": S_of(1, 0),
        "S_C2_PC1": S_of(2, 0),
        "P_C1_PC1": P_of(1, 0),
        "P_C2_PC1": P_of(2, 0),
        "EVR_PC1_pct": float(evr[0]) if evr.size > 0 else None,
        "EVR_PC2_pct": float(evr[1]) if evr.size > 1 else None,
        "L_Assault_PC1": float(L[vi["Assault"], 0]) if "Assault" in vi else None,
        "L_UrbanPop_PC2": (float(L[vi["UrbanPop"], 1])
                           if "UrbanPop" in vi and L.shape[1] > 1 else None),
    }


def cluster_membership(res) -> dict[int, list[str]]:
    """cluster number -> variable names, derived from the per-variable labels."""
    ks = sorted(set(int(x) for x in res.cluster_ids))
    return {k: [nm for nm, c in zip(res.variables, res.cluster_ids) if int(c) == k] for k in ks}

